[{"field": "task_description", "start_line": 1, "end_line": 12, "quote": "def largest_smallest_integers(lst):
    '''
    Create a function that returns a tuple (a, b), where 'a' is
    the largest of negative integers, and 'b' is the smallest
    of positive integers in a list.
    If there is no negative or positive integers, return them as None.

    Examples:
    largest_smallest_integers([2, 4, 1, 3, 5, 7]) == (None, 1)
    largest_smallest_integers([]) == (None, None)
    largest_smallest_integers([0]) == (None, None)
    '''"}, {"field": "incorrect_code", "start_line": 13, "end_line": 28, "quote": "    if len(lst) == 0:
        return (None, None)
    else:
        negatives = []
        positives = []
        for i in lst:
            if i < 0:
                negatives.append(i)
            elif i > 0:
                positives.append(i)
        if len(negatives) == 0:
            return (None, min(positives))
        elif len(positives) == 0:
            return (max(negatives), None)
        else:
            return (max(negatives), min(positives))"}]

[{"field": "task_description", "start_line": 1, "end_line": 12, "quote": "def compare_one(a, b):
    """
    Create a function that takes integers, floats, or strings representing
    real numbers, and returns the larger variable in its given variable type.
    Return None if the values are equal.
    Note: If a real number is represented as a string, the floating point might be . or ,

    compare_one(1, 2.5) ➞ 2.5
    compare_one(1, "2,3") ➞ "2,3"
    compare_one("5,1", "6") ➞ "6"
    compare_one("1", 1) ➞ None
    """"}, {"field": "incorrect_code", "start_line": 13, "end_line": 31, "quote": "    if type(a) == type(b):
        if type(a) == int or type(a) == float:
            if a > b:
                return a
            elif b > a:
                return b
            else:
                return None
        elif type(a) == str:
            a = a.replace(",", ".")
            b = b.replace(",", ".")
            if float(a) > float(b):
                return a
            elif float(b) > float(a):
                return b
            else:
                return None
    else:
        return None"}]

